/* CSS PART 2 OF 4 */

/* =========================================
   HEADER, NAVIGATION, HERO & PRIMARY ACTION
   Josh Brooks Construction and Renovation Inc.
   ========================================= */


/* 1. SITE HEADER
   ========================================= */

.site-header {
  position: sticky;
  z-index: var(--z-header);
  top: 0;
  width: 100%;
  background: rgba(248, 247, 243, 0.97);
  border-bottom: 1px solid var(--color-border);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  width: min(
    var(--container-wide),
    calc(100% - var(--page-gutter) * 2)
  );
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-inline: auto;
}

.site-brand {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.875rem;
  color: var(--color-ink);
}

.site-brand img {
  width: 54px;
  height: 54px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.brand-name {
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: var(--font-weight-heavy);
  letter-spacing: -0.035em;
  line-height: 1.2;
}

.brand-description {
  color: var(--color-muted);
  font-size: 0.625rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.12em;
  line-height: 1.5;
  text-transform: uppercase;
}


/* 2. DESKTOP NAVIGATION
   ========================================= */

.primary-navigation {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(1rem, 2vw, 1.75rem);
}

.primary-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 1.8vw, 1.5rem);
  margin: 0;
  padding: 0;
  list-style: none;
}

.primary-navigation li {
  position: relative;
}

.primary-navigation a:not(.button) {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--color-ink-soft);
  font-size: 0.8125rem;
  font-weight: var(--font-weight-semibold);
  transition: color var(--transition-fast);
}

.primary-navigation a:not(.button):hover,
.primary-navigation a[aria-current="page"] {
  color: var(--color-primary);
}

.primary-navigation a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-primary);
  content: "";
  transition: transform var(--transition-standard);
}

.primary-navigation a:not(.button):hover::after,
.primary-navigation a[aria-current="page"]::after {
  transform: scaleX(1);
}


/* 3. HEADER ACTION
   ========================================= */

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.header-phone {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.125rem;
}

.header-phone-label {
  color: var(--color-muted);
  font-size: 0.625rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.header-phone a {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: var(--font-weight-bold);
  transition: color var(--transition-fast);
}

.header-phone a:hover {
  color: var(--color-primary);
}


/* 4. MOBILE NAVIGATION CONTROLS
   ========================================= */

.mobile-menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  background: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-ink);
}

.mobile-menu-toggle span {
  display: block;
  width: 19px;
  height: 2px;
  background: currentColor;
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.mobile-menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.mobile-menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}


/* 5. SHARED BUTTON SYSTEM
   ========================================= */

.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 0.625rem;
  padding: 0.875rem 1.75rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.025em;
  line-height: 1.2;
  text-align: center;
  transition:
    background var(--transition-standard),
    color var(--transition-standard),
    border-color var(--transition-standard),
    box-shadow var(--transition-standard),
    transform var(--transition-standard);
}

.button:hover {
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0);
}

.button-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.button-primary:hover {
  background: var(--color-primary-dark);
  color: var(--color-white);
  box-shadow: 0 8px 22px rgba(189, 99, 62, 0.23);
}

.button-secondary {
  background: transparent;
  border-color: rgba(25, 43, 53, 0.3);
  color: var(--color-ink);
}

.button-secondary:hover {
  background: var(--color-ink);
  border-color: var(--color-ink);
  color: var(--color-white);
}

.button-light {
  background: var(--color-white);
  color: var(--color-ink);
}

.button-light:hover {
  background: var(--color-primary-light);
  color: var(--color-ink);
}

.button-outline-light {
  background: transparent;
  border-color: rgba(255, 255, 255, 0.65);
  color: var(--color-white);
}

.button-outline-light:hover {
  background: var(--color-white);
  color: var(--color-ink);
}


/* 6. HERO SECTION
   ========================================= */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--color-ink);
  color: var(--color-white);
}

.hero-background {
  position: absolute;
  z-index: -2;
  inset: 0;
  overflow: hidden;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(17, 34, 43, 0.94) 0%,
      rgba(17, 34, 43, 0.83) 38%,
      rgba(17, 34, 43, 0.45) 72%,
      rgba(17, 34, 43, 0.22) 100%
    );
  content: "";
}

.hero-inner {
  display: grid;
  width: min(
    var(--container-wide),
    calc(100% - var(--page-gutter) * 2)
  );
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.8fr);
  align-items: center;
  gap: 3rem;
  margin-inline: auto;
  padding-block: clamp(5rem, 9vw, 8rem);
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: var(--color-primary-light);
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 1.5rem;
  color: var(--color-white);
}

.hero-description {
  max-width: 600px;
  margin-bottom: 2rem;
  color: rgba(255, 255, 255, 0.82);
  font-size: clamp(1.0625rem, 1.8vw, 1.25rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-top: 2rem;
}

.hero-actions .button {
  min-width: 190px;
}


/* 7. HERO CREDENTIALS
   ========================================= */

.hero-credentials {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.25);
}

.hero-credential {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.hero-credential strong {
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: var(--font-weight-bold);
}

.hero-credential span {
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.6875rem;
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.075em;
  text-transform: uppercase;
}

.hero-credential-divider {
  width: 1px;
  height: 34px;
  background: rgba(255, 255, 255, 0.25);
}


/* 8. HERO PROJECT IMAGE FEATURE
   ========================================= */

.hero-feature {
  position: relative;
  align-self: center;
  justify-self: end;
  width: 100%;
  max-width: 420px;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: var(--radius-md);
  backdrop-filter: blur(8px);
}

.hero-feature img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border-radius: 3px;
}

.hero-feature-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 0.25rem 0.25rem;
  color: var(--color-white);
}

.hero-feature-caption strong {
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.8125rem;
}

.hero-feature-caption span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.6875rem;
}


/* 9. HERO DECORATIVE DETAIL
   ========================================= */

.hero-accent {
  position: absolute;
  right: 0;
  bottom: 0;
  width: min(32%, 400px);
  height: 5px;
  background: var(--color-primary);
}

.hero-label {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  margin-bottom: 1.5rem;
  color: var(--color-primary-light);
  font-size: 0.6875rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.hero-label::before {
  width: 26px;
  height: 2px;
  background: currentColor;
  content: "";
}


/* 10. QUICK CONTACT STRIP
   ========================================= */

.contact-strip {
  position: relative;
  z-index: 2;
  background: var(--color-primary);
  color: var(--color-white);
}

.contact-strip-inner {
  display: flex;
  width: min(
    var(--container-width),
    calc(100% - var(--page-gutter) * 2)
  );
  min-height: 76px;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  margin-inline: auto;
}

.contact-strip-copy {
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.875rem;
  font-weight: var(--font-weight-medium);
}

.contact-strip-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
}

.contact-strip a {
  color: var(--color-white);
  font-size: 0.875rem;
  font-weight: var(--font-weight-bold);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
  transition: text-decoration-color var(--transition-fast);
}

.contact-strip a:hover {
  text-decoration-color: currentColor;
}


/* 11. RESPONSIVE HEADER AND HERO
   ========================================= */

@media (max-width: 1100px) {
  .header-inner {
    gap: 1rem;
  }

  .primary-navigation ul {
    gap: 0.875rem;
  }

  .primary-navigation a:not(.button) {
    font-size: 0.75rem;
  }

  .header-phone {
    display: none;
  }

  .hero-inner {
    gap: 2rem;
  }
}

@media (max-width: 850px) {
  .header-inner {
    min-height: 76px;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .primary-navigation {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    align-items: stretch;
    padding: 1rem var(--page-gutter) 1.5rem;
    background: var(--color-paper);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-medium);
  }

  .primary-navigation.is-open {
    display: flex;
    flex-direction: column;
  }

  .primary-navigation ul {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  .primary-navigation li {
    width: 100%;
    border-bottom: 1px solid var(--color-border);
  }

  .primary-navigation a:not(.button) {
    display: flex;
    width: 100%;
    min-height: 48px;
    font-size: 0.875rem;
  }

  .primary-navigation a:not(.button)::after {
    display: none;
  }

  .primary-navigation > .button {
    width: 100%;
    margin-top: 0.75rem;
  }

  .hero {
    min-height: auto;
  }

  .hero-inner {
    grid-template-columns: 1fr;
    gap: 3rem;
    padding-block: 5rem;
  }

  .hero-feature {
    justify-self: start;
    max-width: 500px;
  }

  .hero-feature img {
    aspect-ratio: 16 / 9;
  }
}

@media (max-width: 600px) {
  .brand-name {
    font-size: 0.8rem;
  }

  .brand-description {
    font-size: 0.5625rem;
  }

  .site-brand img {
    width: 44px;
    height: 44px;
  }

  .hero-inner {
    padding-block: 4rem;
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(17, 34, 43, 0.91),
      rgba(17, 34, 43, 0.72)
    );
  }

  .hero h1 {
    font-size: clamp(2.65rem, 11vw, 3.75rem);
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-credentials {
    gap: 1rem;
    margin-top: 2rem;
  }

  .hero-credential-divider {
    display: none;
  }

  .contact-strip-inner {
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 0.75rem;
    padding-block: 1.25rem;
  }

  .contact-strip-links {
    gap: 1rem;
  }
}


/* 12. KEYBOARD AND TOUCH ACCESSIBILITY
   ========================================= */

.mobile-menu-toggle:focus-visible,
.primary-navigation a:focus-visible,
.header-actions a:focus-visible,
.button:focus-visible,
.contact-strip a:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 4px;
}

@media (hover: none) {
  .button:hover {
    transform: none;
  }
}
